import{_ as l,a0 as o,w as d,s as r,ao as t,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"千面 awk | LCTT x X-CMD","titleTemplate":false,"description":"千面 awk | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"千面 awk | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"千面 awk | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191125 The many faces of awk","title":"千面 awk","tag":"201912","desc":""},"relativePath":"201912/20191125 The many faces of awk.md","filePath":"[post].md"}'),c={name:"201912/20191125 The many faces of awk.md"};function h(k,s,g,u,b,f){const n=o("Link");return d(),r("div",null,[s[20]||(s[20]=t(`<h1 id="千面-awk" tabindex="-1">千面 awk <a class="header-anchor" href="#千面-awk" aria-label="Permalink to “千面 awk”">​</a></h1><blockquote><p><code>awk</code> 命令不仅提供了简单的输入字符串筛选功能，还包含提取数据列、打印简单文本、筛选内容——甚至做一些数学计算。</p></blockquote><p><img src="https://images.techhive.com/images/article/2015/09/thinkstockphotos-512100549-100611755-large.jpg" alt="Thinkstock"></p><p>如果你仅使用 <code>awk</code> 选取一行中的特定文本，那么你可能错过了它的很多功能。在这篇文章中，我们会来看看使用 <code>awk</code> 可以帮你做一些其他的什么事情，并提供一些例子。</p><h3 id="提取数据列" tabindex="-1">提取数据列 <a class="header-anchor" href="#提取数据列" aria-label="Permalink to “提取数据列”">​</a></h3><p><code>awk</code> 所提供的最简单与最常用的功能便是从文件或管道传输的数据中选取特定的内容。默认使用空格当做分隔符，这非常简单。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo one two three four five | awk ‘{print $4}’</span></span>
<span class="line"><span>four</span></span>
<span class="line"><span>$ who | awk ‘{print $1}’</span></span>
<span class="line"><span>jdoe</span></span>
<span class="line"><span>fhenry</span></span></code></pre></div><p>空格指的是一系列的 <code>space</code> 或 <code>tab</code> 字符。在下面所展示的命令里，<code>awk</code> 从提供的数据中筛选第一和第四项。</p><p><code>awk</code> 命令也可以通过在其后增加文件名参数的方式从文本文件中获取数据。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;{print $1,$5,$NF}&#39; HelenKellerQuote</span></span>
<span class="line"><span>The beautiful heart.</span></span></code></pre></div><p>（LCTT 译注：“The best and most beautiful things in the world can not be seen or even touched , they must be felt with heart.” ——海伦凯勒）</p><p>在这个例子中，<code>awk</code> 挑选了一行中的第一个、第五个和最后一个字段。</p><p>命令中的 <code>$NF</code> 指定选取每行的最后一个字段。这是因为 <code>NF</code> 代表一行中的<ruby>字段数量<rt>Number of Field</rt></ruby>，也就是 23，而 <code>$NF</code> 就代表着那个字段的值，也就是<code>heart</code>。最后的句号也包含进去了，因为它是最后一个字符串的一部分。</p><p>字段能以任何有用的形式打印。在这个例子中，我们将字段以日期的格式进行打印输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date | awk &#39;{print $4,$3,$2}&#39;</span></span>
<span class="line"><span>2019 Nov 22</span></span></code></pre></div><p>如果你省略了 <code>awk</code> 命令中字段指示符之间的逗号，输出将会挤成一个字符串。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date | awk &#39;{print $4 $3 $2}&#39;</span></span>
<span class="line"><span>2019Nov21</span></span></code></pre></div><p>如果你将通常使用的逗号替换为连字符，<code>awk</code> 就会尝试将两个字段的值相减——或许这并不是你想要的。它不会将连字符插入到输出结果中。相反地，它对输出做了一些数学计算。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date | awk &#39;{print $4-$3-$2}&#39;</span></span>
<span class="line"><span>1997</span></span></code></pre></div><p>在这个例子中，它将年 “2019” 和日期 “22” 相减，并忽略了中间的 “Nov”。</p><p>如果你想要空格之外的字符作为输出分隔符，你可以通过 <code>OFS</code>（<ruby>输出分隔符<rt>output field separator</rt></ruby>）指定分隔符，就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ date | awk &#39;{OFS=&quot;-&quot;; print $4,$3,$2}&#39;</span></span>
<span class="line"><span>2019-Nov-22</span></span></code></pre></div><h3 id="打印简单文本" tabindex="-1">打印简单文本 <a class="header-anchor" href="#打印简单文本" aria-label="Permalink to “打印简单文本”">​</a></h3><p>你也可以使用 <code>awk</code> 简单地显示一些文本。当然了，比起 <code>awk</code> 你可能更想使用 <code>echo</code> 命令。但换句话说，作为 <code>awk</code> 脚本的一部分，打印某些相关性文本将会非常实用。这里有一个没什么用的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;BEGIN {print &quot;Hello, World&quot; }&#39;</span></span>
<span class="line"><span>Hello, World</span></span></code></pre></div><p>下面的例子更加合理，添加一行文本标签来更好的辨识数据。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ who | awk &#39;BEGIN {print &quot;Current logins:&quot;} {print $1}&#39;</span></span>
<span class="line"><span>Current logins:</span></span>
<span class="line"><span>shs</span></span>
<span class="line"><span>nemo</span></span></code></pre></div><h3 id="指定字段分隔符" tabindex="-1">指定字段分隔符 <a class="header-anchor" href="#指定字段分隔符" aria-label="Permalink to “指定字段分隔符”">​</a></h3><p>不是所有的输入都以空格作为分隔符的。如果你的文本通过其它的字符作为分隔符（例如：逗号、冒号、分号），你可以通过 <code>-F</code> 选项（输入分隔符）告诉 <code>awk</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat testfile</span></span>
<span class="line"><span>a:b:c,d:e</span></span>
<span class="line"><span>$ awk -F : &#39;{print $2,$3}&#39; testfile</span></span>
<span class="line"><span>b c,d</span></span></code></pre></div><p>下面是一个更加有用的例子——从冒号分隔的 <code>/etc/passwd</code> 文件中获取数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk -F: &#39;{print $1}&#39; /etc/passwd | head -11</span></span>
<span class="line"><span>root</span></span>
<span class="line"><span>daemon</span></span>
<span class="line"><span>bin</span></span>
<span class="line"><span>sys</span></span>
<span class="line"><span>sync</span></span>
<span class="line"><span>games</span></span>
<span class="line"><span>man</span></span>
<span class="line"><span>lp</span></span>
<span class="line"><span>mail</span></span>
<span class="line"><span>news</span></span>
<span class="line"><span>uucp</span></span></code></pre></div><h3 id="筛选内容" tabindex="-1">筛选内容 <a class="header-anchor" href="#筛选内容" aria-label="Permalink to “筛选内容”">​</a></h3><p>你也可以使用 <code>awk</code> 命令评估字段。例如你仅仅想列出 <code>/etc/passwd</code> 中的用户账号，就可以对第三个字段做一些筛选。下面的例子中我们只关注大于等于 1000 的 UID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk -F&quot;:&quot; &#39; $3 &gt;= 1000 &#39; /etc/passwd</span></span>
<span class="line"><span>nobody:x:65534:65534:nobody:/nonexistent:/usr/sbin/nologin</span></span>
<span class="line"><span>shs:x:1000:1000:Sandra Henry-Stocker,,,:/home/shs:/bin/bash</span></span>
<span class="line"><span>nemo:x:1001:1001:Nemo,,,:/home/nemo:/usr/bin/zsh</span></span>
<span class="line"><span>dory:x:1002:1002:Dory,,,:/home/dory:/bin/bash</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>如果你想为输出增加标题，可以添加 <code>BEGIN</code> 从句：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk -F&quot;:&quot; &#39;BEGIN {print &quot;user accounts:&quot;} $3 &gt;= 1000 &#39; /etc/passwd</span></span>
<span class="line"><span>user accounts:</span></span>
<span class="line"><span>nobody:x:65534:65534:nobody:/nonexistent:/usr/sbin/nologin</span></span>
<span class="line"><span>shs:x:1000:1000:Sandra Henry-Stocker,,,:/home/shs:/bin/bash</span></span>
<span class="line"><span>nemo:x:1001:1001:Nemo,,,:/home/nemo:/usr/bin/zsh</span></span>
<span class="line"><span>dory:x:1002:1002:Dory,,,:/home/dory:/bin/bash</span></span></code></pre></div><p>如果你想要不止一行的标题，你可以通过 <code>&quot;\\n&quot;</code> 分隔输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk -F&quot;:&quot; &#39;BEGIN {print &quot;user accounts\\n=============&quot;} $3 &gt;= 1000 &#39; /etc/passwd</span></span>
<span class="line"><span>user accounts</span></span>
<span class="line"><span>=============</span></span>
<span class="line"><span>nobody:x:65534:65534:nobody:/nonexistent:/usr/sbin/nologin</span></span>
<span class="line"><span>shs:x:1000:1000:Sandra Henry-Stocker,,,:/home/shs:/bin/bash</span></span>
<span class="line"><span>nemo:x:1001:1001:Nemo,,,:/home/nemo:/usr/bin/zsh</span></span>
<span class="line"><span>dory:x:1002:1002:Dory,,,:/home/dory:/bin/bash</span></span></code></pre></div><h3 id="在-awk-中进行数学计算" tabindex="-1">在 awk 中进行数学计算 <a class="header-anchor" href="#在-awk-中进行数学计算" aria-label="Permalink to “在 awk 中进行数学计算”">​</a></h3><p><code>awk</code> 提供了惊人的数学计算能力，并且可以开平方，算 <code>log</code>，算 <code>tan</code> 等等。</p><p>这里有一对例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;BEGIN {print sqrt(2019)}&#39;</span></span>
<span class="line"><span>44.9333</span></span>
<span class="line"><span>$ awk &#39;BEGIN {print log(2019)}&#39;</span></span>
<span class="line"><span>7.61036</span></span></code></pre></div>`,43)),i("p",null,[s[1]||(s[1]=a("想要详细了解 ",-1)),s[2]||(s[2]=i("code",null,"awk",-1)),s[3]||(s[3]=a(" 的数学计算能力，可以看《",-1)),e(n,{href:"https://www.networkworld.com/article/2974753/doing-math-with-awk.html"},{default:p(()=>[...s[0]||(s[0]=[a("使用 awk 进行数学计算",-1)])]),_:1}),s[4]||(s[4]=a("》这篇文章。",-1))]),s[21]||(s[21]=t(`<h3 id="awk-脚本" tabindex="-1">awk 脚本 <a class="header-anchor" href="#awk-脚本" aria-label="Permalink to “awk 脚本”">​</a></h3><p>你也可以使用 <code>awk</code> 写一套单独的脚本。下面的例子模仿了之前写过的一个，不过还计算了系统里账户的数量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/awk -f</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 这一行是注释</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BEGIN {</span></span>
<span class="line"><span>    printf &quot;%s\\n&quot;,&quot;User accounts:&quot;</span></span>
<span class="line"><span>    print &quot;==============&quot;</span></span>
<span class="line"><span>    FS=&quot;:&quot;</span></span>
<span class="line"><span>    n=0</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 现在开始遍历数据</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    if ($3 &gt;= 1000) {</span></span>
<span class="line"><span>        print $1</span></span>
<span class="line"><span>        n ++</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>END {</span></span>
<span class="line"><span>    print &quot;==============&quot;</span></span>
<span class="line"><span>    print n &quot; accounts&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>注意 <code>BEGIN</code> 那一节是如何提供标题、指定字段分隔符和初始化计数器的，它仅在脚本初始化时期执行。这个脚本也包含 <code>END</code> 节，它仅在中间所有命令处理完成之后运行，显示了所有中间小节所筛选数据的最终行数（第三个字段大于等于 1000）。</p><p>作为一个长存于 Unix 之上的命令，<code>awk</code> 依旧提供着非常有用的服务，这也是我几十年前爱上 Unix 的原因之一。</p><hr>`,6)),i("p",null,[s[6]||(s[6]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3454979/the-many-faces-of-awk.html"},{default:p(()=>[...s[5]||(s[5]=[a("https://www.networkworld.com/article/3454979/the-many-faces-of-awk.html",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:p(()=>[...s[7]||(s[7]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[12]||(s[12]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 译者：",-1)),e(n,{href:"https://github.com/LuuMing"},{default:p(()=>[...s[9]||(s[9]=[a("LuuMing",-1)])]),_:1}),s[14]||(s[14]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[16]||(s[16]=[a("Linux中国",-1)])]),_:1}),s[19]||(s[19]=a(" 荣誉推出",-1))])])}const x=l(c,[["render",h]]);export{y as __pageData,x as default};
